9	
10	/// Wordmark "Cerne" centered on [DesignTokens.colorPrimary], loading dots;
11	/// dispatches the app-start event and routes to Home/Chat or Login once
12	/// `SessionBloc` resolves. On a network-error state, shows a visible retry
13	/// action instead of routing away — never stuck (R7; FR-010; Edge Cases).
14	class SplashPage extends StatefulWidget {
15	  const SplashPage({super.key});
16	
17	  @override
18	  State<SplashPage> createState() => _SplashPageState();
19	}
20	
21	class _SplashPageState extends State<SplashPage> {
22	  @override
23	  void initState() {
24	    super.initState();
25	    // Dispatched exactly once per mount — go_router may rebuild this route's
26	    // builder on ancestor rebuilds, but initState only runs once.
27	    context.read<SessionBloc>().add(const AppStarted());
28	  }
29	
30	  @override
31	  Widget build(BuildContext context) {
32	    return Scaffold(
33	      backgroundColor: DesignTokens.colorPrimary,
34	      body: BlocConsumer<SessionBloc, SessionStatus>(
35	        listener: (context, status) {
36	          switch (status) {
37	            case SessionStatusAuthenticated():
38	              context.push(AppRoutes.home);
39	            case SessionStatusUnauthenticated():
40	              context.push(AppRoutes.login);
41	            case SessionStatusChecking():
42	            case SessionStatusExpiredRenewable():
43	            case SessionStatusNetworkError():
44	              break;
45	          }
46	        },
47	        builder: (context, status) {
48	          final isNetworkError = status is SessionStatusNetworkError;
49	          return Center(
50	            child: Column(
51	              mainAxisSize: MainAxisSize.min,
52	              children: [
53	                Text(
54	                  'Cerne',
55	                  style: DesignTokens.textDisplayLg.copyWith(
56	                    color: DesignTokens.colorOnPrimary,
57	                  ),
58	                ),
59	                const SizedBox(height: DesignTokens.spacingLg),
60	                if (isNetworkError)
61	                  _RetryPrompt(
62	                    onRetry: () =>
63	                        context.read<SessionBloc>().add(const AppStarted()),
64	                  )
65	                else
66	                  const _LoadingDots(),
67	              ],
68	            ),
69	          );
70	        },
71	      ),
72	    );
73	  }
74	}
75	
76	class _RetryPrompt extends StatelessWidget {
77	  const _RetryPrompt({required this.onRetry});
78	
79	  final VoidCallback onRetry;
80	
81	  @override
82	  Widget build(BuildContext context) {
83	    return Column(
84	      children: [
85	        Text(
86	          'Sem conexão — não foi possível verificar sua sessão.',
87	          textAlign: TextAlign.center,
88	          style: DesignTokens.textBodyMd.copyWith(
89	            color: DesignTokens.colorOnPrimary,
90	          ),
91	        ),
92	        const SizedBox(height: DesignTokens.spacingMd),
93	        OutlinedButton(
94	          onPressed: onRetry,
95	          style: OutlinedButton.styleFrom(
96	            foregroundColor: DesignTokens.colorOnPrimary,
97	            side: const BorderSide(color: DesignTokens.colorOnPrimary),
98	          ),
99	          child: const Text('Tentar novamente'),
100	        ),
101	      ],
102	    );
103	  }
104	}
105	
106	class _LoadingDots extends StatefulWidget {
107	  const _LoadingDots();
108	
109	  @override
110	  State<_LoadingDots> createState() => _LoadingDotsState();
111	}
112	
113	class _LoadingDotsState extends State<_LoadingDots>
114	    with SingleTickerProviderStateMixin {
115	  late final AnimationController _controller = AnimationController(
116	    vsync: this,
117	    duration: const Duration(milliseconds: 1200),
118	  )..repeat();
119	
120	  @override
121	  void dispose() {
122	    _controller.dispose();
123	    super.dispose();
124	  }
125	
126	  @override
127	  Widget build(BuildContext context) {
128	    return AnimatedBuilder(
129	      animation: _controller,
130	      builder: (context, _) {
131	        return Row(
132	          mainAxisSize: MainAxisSize.min,
133	          children: List.generate(3, (index) {
134	            final phase = (_controller.value + index / 3) % 1.0;
135	            final opacity = 0.3 + 0.7 * (1 - (phase - 0.5).abs() * 2).clamp(0.0, 1.0);
136	            return Padding(
137	              padding: const EdgeInsets.symmetric(
138	                horizontal: DesignTokens.spacingXs,
139	              ),
140	              child: Opacity(
141	                opacity: opacity,
142	                child: Container(
143	                  width: DesignTokens.sizeLoadingDot,
144	                  height: DesignTokens.sizeLoadingDot,
145	                  decoration: const BoxDecoration(
146	                    color: DesignTokens.colorOnPrimary,
147	                    shape: BoxShape.circle,
148	                  ),
149	                ),
150	              ),
151	            );
152	          }),
153	        );
154	      },
155	    );
156	  }
157	}
